SELECT CAST(result."id" AS VARCHAR) AS "id", CAST(result."group_id" AS VARCHAR) AS "group_id", CAST(result."color" AS VARCHAR) AS "color", CAST(result."first" AS INTEGER) AS "first", CAST(result."last" AS INTEGER) AS "last", CAST(result."positions" AS VARCHAR) AS "positions" FROM (SELECT * FROM source_zone) result;
